import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.q07Y7wJQ.js";var i=JSON.parse(`{"title":"Logs","description":"","frontmatter":{"prev":{"text":"Settings","link":"/documentation/settings"},"next":{"text":"Context Menu","link":"/documentation/extension/context-menu"}},"headers":[],"relativePath":"documentation/logs.md","filePath":"documentation/logs.md","lastUpdated":1788551488000}`),a={name:`documentation/logs.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="logs" tabindex="-1">Logs <a class="header-anchor" href="#logs" aria-label="Permalink to “Logs”">​</a></h1><p>Monitor and debug extension activities through a comprehensive logging system that tracks life-cycle events, DOM element matching, and automation operations in real time.</p><div class="logs-methods-grid"><a href="#browser-console-window" class="log-method-card"><div class="log-card-top"><div class="log-icon-box console"><img src="/svg/code.svg" width="16" height="16" alt="Browser Console"></div><span class="log-badge">Method 01</span></div><div class="log-card-title">Browser Console</div><div class="log-card-desc">Real-time raw log stream in Developer Tools console for debugging.</div><div class="log-card-footer"><span class="log-tag">Shortcut: F12</span><span class="log-card-action">View →</span></div></a><a href="#extension-logs-viewer" class="log-method-card"><div class="log-card-top"><div class="log-icon-box viewer"><img src="/svg/card.svg" width="16" height="16" alt="Extension Logs Viewer"></div><span class="log-badge featured">Method 02</span></div><div class="log-card-title">Extension Logs Viewer</div><div class="log-card-desc">On-page drawer &amp; sidebar with instant search, category filters, and zoom.</div><div class="log-card-footer"><span class="log-tag">On-Page Drawer</span><span class="log-card-action">View →</span></div></a><a href="#automation-status-bar" class="log-method-card"><div class="log-card-top"><div class="log-icon-box statusbar"><img src="/svg/system.svg" width="16" height="16" alt="Automation Status Bar"></div><span class="log-badge">Method 03</span></div><div class="log-card-title">Automation Status Bar</div><div class="log-card-desc">Slim 38px toolbar showing live inline updates with attached flyout popover.</div><div class="log-card-footer"><span class="log-tag">Injected Bar</span><span class="log-card-action">View →</span></div></a></div><hr><h2 id="browser-console-window" tabindex="-1">1. Browser Console Window <a class="header-anchor" href="#browser-console-window" aria-label="Permalink to “1. Browser Console Window”">​</a></h2><p>Access real-time log messages directly from your browser&#39;s Developer Tools console for immediate debugging and monitoring during form filling.</p><img src="/image/console-log-01.png" alt="Browser Console Log Messages" style="max-width:100%;height:auto;border-radius:8px;"><h3 id="how-to-open-browser-console" tabindex="-1">How to Open Browser Console <a class="header-anchor" href="#how-to-open-browser-console" aria-label="Permalink to “How to Open Browser Console”">​</a></h3><table tabindex="0"><thead><tr><th>Platform</th><th>Keyboard Shortcut</th><th>Alternative Method</th></tr></thead><tbody><tr><td><strong>Windows / Linux</strong></td><td><kbd>Shift</kbd> + <kbd>Ctrl</kbd> + <kbd>J</kbd> or <kbd>F12</kbd></td><td>Right-click → Inspect → <strong>Console</strong> tab</td></tr><tr><td><strong>macOS</strong></td><td><kbd>Option</kbd> + <kbd>⌘</kbd> + <kbd>J</kbd> or <kbd>F12</kbd></td><td>Right-click → Inspect → <strong>Console</strong> tab</td></tr></tbody></table><h3 id="log-message-levels" tabindex="-1">Log Message Levels <a class="header-anchor" href="#log-message-levels" aria-label="Permalink to “Log Message Levels”">​</a></h3><table tabindex="0"><thead><tr><th>Level</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><span class="log-level-badge info">INFO</span></td><td>Normal operation notices and initialization status</td><td><code>Extension initialized successfully</code></td></tr><tr><td><span class="log-level-badge success">SUCCESS</span></td><td>Successful field fills, saves, and completed actions</td><td><code>Data filled successfully: #username</code></td></tr><tr><td><span class="log-level-badge warn">WARN</span></td><td>Non-critical warnings, fallback selectors, or skipped conditions</td><td><code>Field selector not found, using fallback</code></td></tr><tr><td><span class="log-level-badge error">ERROR</span></td><td>Failed element matching, network errors, or timeout issues</td><td><code>Failed to fill field: input[name=&quot;email&quot;]</code></td></tr><tr><td><span class="log-level-badge debug">DEBUG</span></td><td>Detailed element detection and property extraction traces</td><td><code>Processing form field: #username</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Pro Tip</p><p>Keep the browser console open while configuring new forms to immediately inspect matching selectors, element values, and execution steps.</p></div><hr><h2 id="extension-logs-viewer" tabindex="-1">2. Extension Logs Viewer <a class="header-anchor" href="#extension-logs-viewer" aria-label="Permalink to “2. Extension Logs Viewer”">​</a></h2><p>The <strong>Extension Logs Viewer</strong> is a dedicated slide-over panel and docked sidebar that opens directly over the active web page without needing browser developer tools.</p><ul><li><strong>Full Documentation</strong>: <img src="/svg/settings.svg" class="doc-icon" width="16" height="16" alt="Settings"> <a href="/documentation/settings.html#show-extension-logs-viewer">Settings → Visual Feedback → Show Extension Logs Viewer</a></li></ul><img src="/image/logs-viewer.png" alt="Extension Logs Viewer Interface" style="max-width:100%;width:480px;height:auto;border-radius:8px;margin:16px 0;"><h3 id="logs-viewer-capabilities" tabindex="-1">Key Capabilities <a class="header-anchor" href="#logs-viewer-capabilities" aria-label="Permalink to “Key Capabilities”">​</a></h3><ul><li><strong>Dock &amp; Floating Modes</strong>: Toggle between a floating slide-over drawer and a docked side panel.</li><li><strong>Search Filtering</strong>: Filter logs instantly by keyword, selector name, URL, or message text.</li><li><strong>Category Tabs</strong>: Filter by <strong>All</strong>, <strong>Group</strong> (segments &amp; loops), <strong>Success</strong>, <strong>Warn</strong>, or <strong>Error</strong>.</li><li><strong>Stream Controls</strong>: Pause live streaming to freeze and inspect events while automation continues.</li><li><strong>Export Logs</strong>: Download current session logs for debugging and offline review.</li><li><strong>Visual Customization</strong>: Width presets (420px, 520px, 680px, 880px), zoom scale adjustments, and Light/Dark themes.</li></ul><hr><h2 id="automation-status-bar" tabindex="-1">3. Automation Status Bar <a class="header-anchor" href="#automation-status-bar" aria-label="Permalink to “3. Automation Status Bar”">​</a></h2><p>When enabled, the extension injects a sleek status bar at the top or bottom of the active page that shows real-time progress, entry numbers, and live log updates.</p><ul><li><strong>Full Documentation</strong>: <img src="/svg/settings.svg" class="doc-icon" width="16" height="16" alt="Settings"> <a href="/documentation/settings.html#automation-status-bar">Settings → Automation Status Bar</a> &amp; <a href="/documentation/settings.html#show-extension-logs-in-status-bar">Show Extension Logs in Status Bar</a></li></ul><img src="/image/status-bar-01.png" alt="Automation Status Bar" style="max-width:100%;height:auto;border-radius:8px;margin:16px 0;"><h3 id="status-bar-logging-features" tabindex="-1">Status Bar Logging Features <a class="header-anchor" href="#status-bar-logging-features" aria-label="Permalink to “Status Bar Logging Features”">​</a></h3><ul><li><strong>Live Inline Updates</strong>: Latest operation and status messages stream right in the bar without covering content.</li><li><strong>Attached Logs Popover</strong>: Clicking the logs section on the status bar opens a compact flyout showing recent log entries.</li><li><strong>Lightweight &amp; Non-Intrusive</strong>: Monitor progress at a glance without opening developer panels.</li><li><strong>Position &amp; Docking</strong>: Place the bar at the top or bottom, or minimize it into a floating dock corner pill.</li></ul><div class="info custom-block"><p class="custom-block-title">Dismissing Status Bar Programmatically</p><p>If you need to close the status bar during automated tasks (e.g., before taking full-page screenshots), call the <a href="/documentation/functions.html#closestatusbar"><code>closeStatusBar</code></a> predefined function in your workflow.</p></div><hr><h2 id="custom-javascript-logging" tabindex="-1">Logging from Custom JavaScript <a class="header-anchor" href="#custom-javascript-logging" aria-label="Permalink to “Logging from Custom JavaScript”">​</a></h2><p>You can also send your own structured log messages from <a href="/documentation/field-types/javascript-code.html">JavaScript Code</a> fields using the <code>$fns.log</code> utility. These messages appear automatically in both the <strong>Browser Console</strong> and the <strong>Extension Logs Viewer</strong>:</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// Log a success message</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $fns.log.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">success</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Data filled successfully&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { row: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> });</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// Log an error message</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $fns.log.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">error</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Submit button not found&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// Log a warning message</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $fns.log.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">warning</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Field skipped due to condition&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>For more details on custom scripting, see <img src="/svg/code.svg" class="doc-icon" width="16" height="16" alt="Functions"> <a href="/documentation/field-types/javascript-code.html#logging-functions">JavaScript Code Field Type</a>.</p><hr><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to “Related Documentation”">​</a></h2><ul><li><img src="/svg/settings.svg" class="doc-icon" width="16" height="16" alt="Settings"> <a href="/documentation/settings.html">Extension Settings</a> — Configure visual feedback, status bar, and logging options.</li><li><img src="/svg/code.svg" class="doc-icon" width="16" height="16" alt="Functions"> <a href="/documentation/functions.html">Predefined Functions</a> — Built-in automation helper functions.</li><li><img src="/svg/form.svg" class="doc-icon" width="16" height="16" alt="Form Fields"> <a href="/documentation/form-fields/field.html">Form Fields Overview</a> — Field configuration and options.</li></ul>`,35)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};